 /** Stable, session-independent match identifier for URL routing.
  *
- * Slug = `${cargoId}--${vesselId}`. The double-dash separator is safe
- * because email IDs in demo data use single dashes only (e.g. "demo-cargo-001").
- * Production email IDs are UUIDs or similar — never contain `--`.
+ * Two formats:
+ *  - Legacy (2-arg):  `${cargoId}--${vesselId}`
+ *  - Item-aware (4-arg): `${cargoId}--${cargoItemIndex}--${vesselId}--${vesselItemIndex}`
+ *
+ * The double-dash separator is safe because email IDs in demo data use single
+ * dashes only (e.g. "demo-cargo-001"). Production email IDs are UUIDs or
+ * similar — never contain `--`.
+ *
+ * Item indices are included in new callers so multiple matches from the same
+ * email pair (e.g. an email containing two cargoes) each get a distinct, routable URL.
  */

-export function toMatchSlug(cargoId: string, vesselId: string): string {
-  return `${cargoId}--${vesselId}`;
+export function toMatchSlug(cargoId: string, vesselId: string): string;
+export function toMatchSlug(cargoId: string, cargoItemIndex: number, vesselId: string, vesselItemIndex: number): string;
+export function toMatchSlug(
+  cargoId: string,
+  cargoItemIndexOrVesselId: number | string,
+  vesselId?: string,
+  vesselItemIndex?: number,
+): string {
+  if (typeof cargoItemIndexOrVesselId === 'string') {
+    return `${cargoId}--${cargoItemIndexOrVesselId}`;
+  }
+  return `${cargoId}--${cargoItemIndexOrVesselId}--${vesselId}--${vesselItemIndex ?? 0}`;
+}
+
+export interface MatchSlugKeys {
+  cargo_id: string;
+  cargo_item_index?: number;
+  vessel_id: string;
+  vessel_item_index?: number;
 }

-export function fromMatchSlug(
-  slug: string,
-): { cargo_id: string; vessel_id: string } | null {
-  const idx = slug.indexOf('--');
-  if (idx < 1) return null; // no separator or empty cargo_id
-  const cargo_id = slug.slice(0, idx);
-  const vessel_id = slug.slice(idx + 2);
-  if (!vessel_id) return null;
-  return { cargo_id, vessel_id };
+export function fromMatchSlug(slug: string): MatchSlugKeys | null {
+  const parts = slug.split('--');
+  if (parts.length === 2) {
+    // Legacy format: cargo_id--vessel_id
+    const cargo_id = parts[0];
+    const vessel_id = parts[1];
+    if (!cargo_id || !vessel_id) return null;
+    return { cargo_id, vessel_id };
+  }
+  if (parts.length >= 4) {
+    // Item-aware format: cargo_id--cargo_item_index--vessel_id--vessel_item_index
+    const cargo_id = parts[0];
+    const cargo_item_index = parseInt(parts[1], 10);
+    const vessel_id = parts[2];
+    const vessel_item_index = parseInt(parts[3], 10);
+    if (!cargo_id || !vessel_id) return null;
+    if (!Number.isFinite(cargo_item_index) || !Number.isFinite(vessel_item_index)) return null;
+    return { cargo_id, cargo_item_index, vessel_id, vessel_item_index };
+  }
+  return null;
 }
