new file mode 100644
index 00000000..b17e75c2
--- /dev/null
+++ b/lib/migrations/051-matches-item-pair-unique.ts
@@ -0,0 +1,41 @@
+import type { Migration } from './types';
+
+const migration051: Migration = {
+  version: 51,
+  name: '051-matches-item-pair-unique',
+  up(db) {
+    // Drop the old email-pair unique index (cargo_id, vessel_id, user_id) and
+    // replace it with an item-pair index that includes item indices. This allows
+    // multiple matches per email pair when a letter contains more than one cargo
+    // or vessel (second cargo of a letter was previously lost — C.5 audit fix).
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+
+    // Remove any pre-existing duplicates on the new key, keeping the earliest row.
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid) FROM matches
+        GROUP BY cargo_id, COALESCE(cargo_item_index, 0),
+                 vessel_id, COALESCE(vessel_item_index, 0),
+                 COALESCE(user_id, '')
+      )
+    `);
+
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_item_pair
+      ON matches(cargo_id, COALESCE(cargo_item_index, 0),
+                 vessel_id, COALESCE(vessel_item_index, 0),
+                 COALESCE(user_id, ''))
+    `);
+  },
+  down(db) {
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_item_pair`);
+    // Restore original email-pair constraint (may fail if duplicates exist).
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''))
+    `);
+  },
+};
+
+export default migration051;
