+import type { Migration } from './types';
+
+const migration051: Migration = {
+  version: 51,
+  name: '051-matches-item-unique',
+  up(db) {
+    // Drop the old email-pair-only unique index — it prevented the second cargo
+    // of a multi-cargo letter from being stored alongside the first.
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+
+    // Remove any item-level duplicates (same cargo_id + vessel_id + user_id +
+    // cargo_item_index + vessel_item_index), keeping the earliest row.
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid) FROM matches
+        GROUP BY cargo_id, vessel_id,
+                 COALESCE(user_id, ''),
+                 COALESCE(cargo_item_index, 0),
+                 COALESCE(vessel_item_index, 0)
+      )
+    `);
+
+    // New index — one row per (cargo email, vessel email, user, cargo item, vessel item).
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user_items
+      ON matches(
+        cargo_id, vessel_id,
+        COALESCE(user_id, ''),
+        COALESCE(cargo_item_index, 0),
+        COALESCE(vessel_item_index, 0)
+      )
+    `);
+  },
+  down(db) {
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user_items`);
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''))
+    `);
+  },
+};
+
+export default migration051;
